70	    int cur_button = read_buttons();
71		int changed = last_button ^ cur_button;
72		int status = 0;
73	    uint32_t ticks = chVTGetSystemTime();
74		if (changed & (1<<BIT_PUSH)) {
75			if (ticks >= last_button_down_ticks + BUTTON_DEBOUNCE_TICKS) {
76	            if (!(cur_button & (1<<BIT_PUSH))) {
77					// button released
78	              if (button_event_inhibited) {
79	                button_event_inhibited = 0;
80	              } else {
81	                status |= EVT_BUTTON_SINGLE_CLICK;
82	              }
83				} else {
84					// button pushed
85	                if (ticks < last_button_down_ticks + BUTTON_DOUBLE_TICKS) {
86						status |= EVT_BUTTON_DOUBLE_CLICK;
87					} else {
88						last_button_down_ticks = ticks;
89					}
90				}
91			}
92		} else {
93			// button unchanged
94	        if ((cur_button & (1<<BIT_PUSH))
95	            && !button_event_inhibited
96				&& ticks >= last_button_down_ticks + BUTTON_DOWN_LONG_TICKS) {
97				status |= EVT_BUTTON_DOWN_LONG;
98	            button_event_inhibited = 1;
99			}
100		}
101	
102	    last_button = cur_button;
103	
104		return status;
105	}
